// GENERATED by medusa-integrations: copied from kit/admin/integrations.tsx by scripts/kit-sync.mjs. Do not edit by hand.
import { clx, Container, Skeleton, Text } from "@medusajs/ui"
import { type ComponentType, type CSSProperties, useState } from "react"
import { useTranslation } from "react-i18next"
import { Link } from "react-router-dom"

/**
 * Integrations on Medusa's own pages, the same in every plugin.
 *
 * Every plugin of the repo ships this file (kit). Each one registers what it
 * has to show, in a registry shared through `globalThis`:
 *
 * - tabs on detail pages (order, customer): its panel, with a state colour;
 * - signals on overview cards (orders list, catalog, product): a tile, a row
 *   or a chip with a count and a link.
 *
 * Each plugin also has the same widget in each zone. Only the first plugin
 * that claimed a zone renders there, so a page gets one card with every
 * installed integration, never one card per plugin.
 *
 * The registry key carries a version. New fields are added so that plugins
 * built with an older kit keep working; a breaking change gets a new key.
 */

type IconComponent = ComponentType<{ style?: CSSProperties; color?: string; className?: string }>

/** The colour-coding of states: green ok, orange attention, red error, blue info, grey nothing. */
export type Level = "ok" | "info" | "warn" | "error" | "none"

export const LEVEL_COLOR: Record<Level, string> = {
  ok: "var(--tag-green-icon)",
  info: "var(--tag-blue-icon)",
  warn: "var(--tag-orange-icon)",
  error: "var(--tag-red-icon)",
  none: "var(--tag-neutral-icon)",
}

/** Errors first, then what needs attention. */
export const LEVEL_RANK: Record<Level, number> = { error: 0, warn: 1, info: 2, ok: 3, none: 4 }

/** How an integration looks: the same tile as its sidebar entry. */
export type Brand = {
  /** Translation key of the name (in the plugin's own namespace), or the name itself. */
  label: string
  /** Icon on a coloured tile... */
  icon?: IconComponent
  color?: string
  /** ...or the service's logo. `logoFill` for logos that are a coloured square themselves. */
  logo?: string
  logoFill?: boolean
}

/* Detail pages: tabs ------------------------------------------------------- */

/**
 * Detail pages with a tabbed Integrations card, and the zone each uses. On
 * the product page the card sits under "Product at a glance", which
 * renders it (see `ProductOverview`), so product tabs need no widget of
 * their own: registering them is enough.
 */
export const DETAIL_ZONES = {
  order: "order.details.before",
  customer: "customer.details.before",
  product: "product.details.before",
} as const
export type DetailPage = keyof typeof DETAIL_ZONES

/** What a tab reports: whether it applies to the record, and its colour. */
export type TabState = { visible: boolean; level: Level; loading?: boolean }

/** The record Medusa passes to the widget (order, customer, product); tabs read what they need. */
export type EntityLike = { id: string } & Record<string, any>
/** @deprecated Use EntityLike. */
export type OrderLike = EntityLike

export type DetailTab = {
  /** The plugin's namespace, e.g. "stripe". */
  id: string
  brand: Brand
  /** Lower comes first (payments, shipping, documents, messages, the rest). */
  order: number
  /** A React hook: called on every render of the card, in a stable order. */
  useState: (entity: EntityLike) => TabState
  Panel: ComponentType<{ order: EntityLike; entity: EntityLike }>
}
/** @deprecated Use DetailTab. */
export type OrderTab = DetailTab

/* Overview cards: signals --------------------------------------------------- */

/** Overview cards on Medusa's pages, and the zone each uses. */
export const OVERVIEW_ZONES = {
  orders: "order.list.before",
  catalog: "product.list.before",
  product: "product.details.before",
} as const
export type OverviewScope = keyof typeof OVERVIEW_ZONES

/**
 * One thing an integration reports on an overview card. Texts are already
 * translated by the plugin. Shown as a chip by default; `tile` adds it to
 * the card's tiles (orders), `row` shows it as a line (product).
 */
export type Signal = {
  key: string
  level: Level
  text: string
  count?: number
  href?: string
  tile?: { label: string; hint?: string }
  row?: boolean
}

/** What a plugin's signal hook receives: the product on the product card. */
export type SignalContext = { product?: EntityLike }

export type SignalProvider = {
  id: string
  brand: Brand
  order: number
  /** A React hook returning the plugin's signals for this card (empty when it has none). */
  useSignals: (context: SignalContext) => Signal[]
}

/* Registry ------------------------------------------------------------------ */

type Registry = {
  orderTabs: DetailTab[]
  owners: Record<string, string>
  tabs?: Partial<Record<DetailPage, DetailTab[]>>
  signals?: Partial<Record<OverviewScope, SignalProvider[]>>
}

const KEY = Symbol.for("bitshaft.medusa-integrations.registry.v1")

function registry(): Registry {
  const store = globalThis as typeof globalThis & { [KEY]?: Registry }
  const r = (store[KEY] ??= { orderTabs: [], owners: {} })
  r.tabs ??= {}
  r.signals ??= {}
  return r
}

const byOrder = <T extends { order: number; id: string }>(a: T, b: T) => a.order - b.order || a.id.localeCompare(b.id)

function tabsOf(page: DetailPage): DetailTab[] {
  const r = registry()
  // The order page's list predates `tabs`; older kits still write to it.
  if (page === "order") return r.orderTabs
  return (r.tabs![page] ??= [])
}

/** Registers the plugin's tab on a detail page (once, at module load of its widget). */
export function registerTab(page: DetailPage, tab: DetailTab): void {
  const list = tabsOf(page)
  if (list.some((t) => t.id === tab.id)) return
  list.push(tab)
  list.sort(byOrder)
}

/** @deprecated Use registerTab("order", tab). */
export const registerOrderTab = (tab: DetailTab) => registerTab("order", tab)

/** Registers the plugin's signals on an overview card (once, at module load of its widget). */
export function registerSignals(scope: OverviewScope, provider: SignalProvider): void {
  const list = (registry().signals![scope] ??= [])
  if (list.some((p) => p.id === provider.id)) return
  list.push(provider)
  list.sort(byOrder)
}

export function signalProviders(scope: OverviewScope): SignalProvider[] {
  return [...(registry().signals![scope] ?? [])]
}

export const ORDER_ZONE = DETAIL_ZONES.order

/** The first plugin to claim a zone renders its card; the others render nothing there. */
export function claimZone(zone: string, owner: string): void {
  registry().owners[zone] ??= owner
}

export const isOwner = (zone: string, owner: string) => registry().owners[zone] === owner

/* Pieces -------------------------------------------------------------------- */

/** The coloured tile of an integration, in any size. */
export const BrandTile = ({ brand, size = 20 }: { brand: Brand; size?: number }) => {
  const Icon = brand.icon
  if (brand.logo) {
    return (
      <span
        aria-hidden
        className={clx(
          "flex shrink-0 items-center justify-center overflow-hidden rounded-[4px] shadow-borders-base",
          !brand.logoFill && "bg-white p-px"
        )}
        style={{ width: size, height: size }}
      >
        <img src={brand.logo} alt="" className={clx("size-full", brand.logoFill ? "object-cover" : "object-contain")} />
      </span>
    )
  }
  return (
    <span
      aria-hidden
      className="flex shrink-0 items-center justify-center rounded-[4px]"
      style={{ width: size, height: size, backgroundColor: brand.color, color: "#ffffff" }}
    >
      {Icon && <Icon color="currentColor" style={{ width: size * 0.7, height: size * 0.7 }} />}
    </span>
  )
}

export const LevelDot = ({ level, className }: { level: Level; className?: string }) => (
  <span
    aria-hidden
    className={clx("inline-block size-1.5 shrink-0 rounded-full", className)}
    style={{ backgroundColor: LEVEL_COLOR[level] }}
  />
)

/** The plugin's name, translated by its own namespace. */
export function useBrandLabel() {
  const { t } = useTranslation()
  return (brand: Brand) => t(brand.label, { defaultValue: brand.label })
}

/** A chip: brand tile, name, what it reports and its dot; a link when it has one. */
export const SignalChip = ({ brand, signal }: { brand: Brand; signal: Signal }) => {
  const label = useBrandLabel()
  const content = (
    <>
      <BrandTile brand={brand} size={16} />
      <span className="txt-compact-xsmall-plus text-ui-fg-base">{label(brand)}</span>
      <span className="txt-compact-xsmall text-ui-fg-subtle">{signal.text}</span>
      <LevelDot level={signal.level} />
    </>
  )
  const className = "flex items-center gap-x-1.5 rounded-md bg-ui-bg-base px-2 py-1 shadow-borders-base transition-fg"
  return signal.href ? (
    <Link to={signal.href} className={clx(className, "hover:bg-ui-bg-base-hover")}>
      {content}
    </Link>
  ) : (
    <span className={className}>{content}</span>
  )
}

/** The "Integrations" strip at the bottom of an overview card; nothing when no plugin reports anything. */
export const SignalStrip = ({
  title,
  items,
}: {
  title: string
  items: Array<{ provider: SignalProvider; signal: Signal }>
}) => {
  if (!items.length) return null
  return (
    <div className="flex flex-wrap items-center gap-2 px-6 py-3">
      <Text size="xsmall" weight="plus" className="mr-1 uppercase tracking-wide text-ui-fg-muted">
        {title}
      </Text>
      {items.map(({ provider, signal }) => (
        <SignalChip key={`${provider.id}:${signal.key}`} brand={provider.brand} signal={signal} />
      ))}
    </div>
  )
}

/**
 * Every provider's signals for a card. Hooks are called on every render in a
 * stable order (the providers are a snapshot taken on the first render).
 */
export function useSignals(scope: OverviewScope, context: SignalContext) {
  const [providers] = useState(() => signalProviders(scope))
  const lists = providers.map((provider) => provider.useSignals(context))
  return providers.flatMap((provider, i) => lists[i].map((signal) => ({ provider, signal })))
}

/* Detail card ---------------------------------------------------------------- */

/**
 * The Integrations card of a detail page: one tab per integration that
 * applies, each with its brand tile and a dot in its state's colour. The tab
 * that needs attention most opens first. Rendered by the plugin that claimed
 * the zone; `owner` is the calling plugin's namespace.
 */
export const DetailIntegrations = ({ page, owner, entity }: { page: DetailPage; owner: string; entity: EntityLike }) =>
  isOwner(DETAIL_ZONES[page], owner) ? <DetailCard page={page} entity={entity} /> : null

/** @deprecated Use DetailIntegrations with page="order". */
export const OrderIntegrations = ({ owner, order }: { owner: string; order: EntityLike }) => (
  <DetailIntegrations page="order" owner={owner} entity={order} />
)

/** The tabbed Integrations card itself, for a kit card that already owns its zone. */
export const DetailCard = ({ page, entity }: { page: DetailPage; entity: EntityLike }) => {
  const label = useBrandLabel()
  // A snapshot: every tab's hook is called on every render, in this order.
  const [tabs] = useState(() => [...tabsOf(page)])
  const states = tabs.map((tab) => tab.useState(entity))
  const [selected, setSelected] = useState<string | null>(null)

  const shown = tabs.map((tab, i) => ({ tab, state: states[i] })).filter(({ state }) => state.visible || state.loading)
  if (!shown.length) return null

  const ready = shown.filter(({ state }) => state.visible)
  const first = [...ready].sort((a, b) => LEVEL_RANK[a.state.level] - LEVEL_RANK[b.state.level])[0]?.tab.id
  const active = ready.find(({ tab }) => tab.id === selected)?.tab ?? ready.find(({ tab }) => tab.id === first)?.tab
  const Panel = active?.Panel

  return (
    <Container className="overflow-hidden divide-y p-0">
      <div role="tablist" className="flex flex-wrap items-center gap-1 bg-ui-bg-subtle px-4 py-2">
        {shown.map(({ tab, state }) =>
          state.visible ? (
            <button
              key={tab.id}
              type="button"
              role="tab"
              aria-selected={tab.id === active?.id}
              onClick={() => setSelected(tab.id)}
              className={clx(
                "txt-compact-small-plus flex items-center gap-x-2 rounded-md px-2.5 py-1.5 transition-fg outline-none",
                "focus-visible:shadow-borders-focus",
                tab.id === active?.id
                  ? "bg-ui-bg-base text-ui-fg-base shadow-borders-interactive-with-active"
                  : "text-ui-fg-subtle hover:bg-ui-bg-base-hover hover:text-ui-fg-base"
              )}
            >
              <BrandTile brand={tab.brand} size={18} />
              {label(tab.brand)}
              <LevelDot level={state.level} />
            </button>
          ) : (
            <span key={tab.id} className="flex items-center gap-x-2 px-2.5 py-1.5 opacity-60">
              <BrandTile brand={tab.brand} size={18} />
              <Skeleton className="h-3 w-12" />
            </span>
          )
        )}
      </div>
      <div role="tabpanel">
        {active && Panel ? <Panel order={entity} entity={entity} /> : <Skeleton className="m-6 h-24" />}
      </div>
    </Container>
  )
}
